-- ExamGrind daily current-affairs desk: verified recovery window, 21-25 October 2026.
-- Each brief is independently written from the linked official primary source.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-10-27-pm-samajik-sahayata-yojana$$, $$2026-10-27$$,
$$National Social Assistance Programme continued and renamed Pradhan Mantri Samajik Sahayata Yojana$$,
$$The Union Cabinet approved continuation of the National Social Assistance Programme for 2026-27 to 2030-31 with an outlay of Rs 53,428 crore. The programme is to be called Pradhan Mantri Samajik Sahayata Yojana, with revised disability-pension eligibility and assistance.$$,
$$This is a high-yield social-justice and welfare-policy update: it links a central social-assistance programme with Article 41, disability law, centrally funded support and State/UT implementation.$$,
$$NSAP began in 1995 to provide public assistance to poor households. The Cabinet approval keeps the old-age pension, widow pension and family-benefit components in their existing form, while changing the disability-pension component. Its benchmark-disability threshold moves from 80% to 40%, aligning with the Rights of Persons with Disabilities Act, 2016; the age floor is removed. The release says implementation guidelines are to follow, so students should not treat the announcement as proof that every administrative detail has already changed on the ground.$$,
$$Cabinet approves continuation of the National Social Assistance Programme for five years from 2026-27 to 2030-31$$,
$$https://www.pib.gov.in/PressReleasepage.aspx?PRID=2323264&l=&lang=2&reg=48$$,
$$Cabinet Secretariat / Press Information Bureau$$, $$2026-10-14$$,
$$["NSAP is renamed Pradhan Mantri Samajik Sahayata Yojana.","The continuation runs from 2026-27 to 2030-31 with a Rs 53,428 crore outlay.","The disability-pension benchmark changes to 40% disability and the minimum age is removed.","NSAP is linked to Article 41 and provides 100% central assistance."]$$::jsonb,
$$[{"question":"Which NSAP component changes most directly under the Cabinet decision?","answer":"The disability-pension component; its eligibility, coverage and central assistance are revised, while the old-age, widow and family-benefit components continue in their existing form."}]$$::jsonb,
$${"title":"Social assistance: policy chain","steps":["Article 41 sets the constitutional direction.","NSAP provides central social assistance.","The 2026 decision continues and renames the programme.","Revised disability-pension rules are implemented through guidelines and State/UT delivery."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-flex-fuel-e85-e100-cmvr-amendment$$, $$2026-10-27$$,
$$CMVR amendments facilitate E85 and E100 flex-fuel vehicles$$,
$$The Ministry of Road Transport and Highways notified amendments to the Central Motor Vehicles Rules, 1989, to facilitate flex-fuel vehicles capable of using E85 and other high-ethanol fuels. The changes expressly include E100 in emission-certification provisions.$$,
$$This is a strong environment, energy and regulation brief: it tests ethanol-blend notation, vehicle certification and the difference between a fuel-policy target and technical vehicle rules.$$,
$$E85 denotes a petrol-ethanol blend containing up to 85% ethanol by volume; E100 refers to ethanol fuel. Flex-fuel vehicles are specially designed to run on a range of petrol-ethanol blends. The notified changes do not mean that every existing petrol vehicle can use E85 or E100: certified vehicles must meet applicable safety and emission requirements.$$,
$$MoRTH updates rules to facilitate E85/E100 flex-fuel vehicles$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2328642&lang=1&reg=3$$,
$$Ministry of Road Transport and Highways / Press Information Bureau$$, $$2026-10-26$$,
$$["The amendments are to the Central Motor Vehicles Rules, 1989.","E85 contains up to 85% ethanol by volume.","The updated certification provisions expressly include E100 alongside E85.","Flex-fuel vehicles must meet the applicable emission and safety requirements."]$$::jsonb,
$$[{"question":"Does an E85/E100 rule amendment mean an ordinary petrol vehicle is automatically suitable for these fuels?","answer":"No. The rules concern certified flex-fuel vehicles, which must meet the relevant safety and emission requirements."}]$$::jsonb,
$${"title":"From fuel blend to compliant vehicle","steps":["A fuel blend is defined by its ethanol share.","A flex-fuel vehicle is designed for appropriate blends.","Certification checks emission and safety requirements.","Rule changes enable compliant E85/E100 vehicle adoption."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-nsdc-social-stock-exchange-debut$$, $$2026-10-27$$,
$$NSDC makes its Social Stock Exchange debut with a zero-coupon, zero-principal issue$$,
$$The National Skill Development Corporation made its debut on the NSE Social Stock Exchange and issued its first Zero Coupon Zero Principal instrument. NABARD subscribed Rs 4 crore for an international-employment skilling initiative for 600 young people from economically weaker OBC households in Madhya Pradesh.$$,
$$This is useful for economy, financial markets and skilling: it tests the Social Stock Exchange as an outcome-oriented financing channel rather than an ordinary share-market listing.$$,
$$NSDC works under the Ministry of Skill Development and Entrepreneurship. A Zero Coupon Zero Principal instrument does not work like a conventional interest-bearing bond or equity share: it is designed for social-sector fundraising and its value lies in the supported social outcome. The official release describes the associated programme as involving government, private CSR, retail capital and training partners.$$,
$$NSDC’s debut on NSE Social Stock Exchange and maiden Zero Coupon Zero Principal issue$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2326769&lang=1&reg=3$$,
$$Ministry of Skill Development and Entrepreneurship / Press Information Bureau$$, $$2026-10-22$$,
$$["NSDC works under the Ministry of Skill Development and Entrepreneurship.","Its debut was on the NSE Social Stock Exchange.","NABARD subscribed Rs 4 crore to NSDC’s maiden ZCZP issue.","The linked initiative aims to support international-employment preparation for 600 young people from economically weaker OBC households in Madhya Pradesh."]$$::jsonb,
$$[{"question":"Is a Zero Coupon Zero Principal instrument the same as an ordinary equity share?","answer":"No. It is a social-sector fundraising instrument and does not operate as a conventional ownership share or interest-paying bond."}]$$::jsonb,
$${"title":"Outcome-oriented social finance","steps":["A social project identifies a measurable outcome.","A Social Stock Exchange can connect it with eligible capital.","A ZCZP issue channels support without conventional coupon or principal repayment.","Skilling partners deliver the intended beneficiary outcome."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-enhanced-nmms-vb-g-ram-g$$, $$2026-10-27$$,
$$Enhanced NMMS app adds safeguards for attendance under VB-G RAM G$$,
$$The Ministry of Rural Development launched an enhanced National Mobile Monitoring System app for worker attendance under VB-G RAM G. The update adds device-level security, AI-based verification, offline recording and an exception route for genuine authentication difficulties.$$,
$$It illustrates how digital public-service delivery must balance fraud controls with access for workers in low-connectivity areas—an important governance and rural-development theme.$$,
$$The app records attendance, while the underlying employment programme provides the work-support framework. According to the release, the updated app was developed with IIT Madras support. Face authentication can help reduce impersonation, but the stated offline and exception provisions recognise that connectivity and authentication failures should not automatically deny a genuine worker an entitlement.$$,
$$Enhanced NMMS app version with advanced security features for VB-G RAM G$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2327556&lang=1&reg=1$$,
$$Ministry of Rural Development / Press Information Bureau$$, $$2026-10-23$$,
$$["NMMS is the National Mobile Monitoring System app.","The update is for recording worker attendance under VB-G RAM G.","It adds device-level security and AI-based verification.","It also permits offline attendance recording and an exception mechanism for genuine authentication difficulties."]$$::jsonb,
$$[{"question":"Why are offline and exception features significant in a digital attendance system?","answer":"They help prevent connectivity or authentication problems from excluding genuine workers while the system still uses safeguards against false attendance."}]$$::jsonb,
$${"title":"Accountable but accessible digital attendance","steps":["Workers report at a worksite.","The app records attendance with security checks.","Offline and exception paths cover genuine access problems.","Verified records support wage protection and programme accountability."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-plfs-2027-sampling-consultation$$, $$2026-10-27$$,
$$NSO proposes PLFS 2027 sampling and schedule changes, including better coverage of platform work$$,
$$The National Statistics Office has invited comments on changes proposed for the Periodic Labour Force Survey from January 2027. The proposal includes a separate sampling stratum for digital-platform workers and additional questions on unpaid and care activities.$$,
$$This is a valuable statistics-and-economy item because changes in survey design affect what labour-market indicators capture and how time series should be interpreted.$$,
$$PLFS has been conducted by NSO since 2017. Its design was revamped from January 2025 for monthly, quarterly and annual estimates. For the proposed 2027 Panel 6, NSO says the existing design did not capture enough digital-platform workers; it therefore proposes a dedicated Second Stage Stratum. The consultation also proposes a three-month transition using both old and new frames, so students should distinguish a proposal from a released series change.$$,
$$Changes in PLFS schedule and estimation procedure from January 2027 — inviting comments$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2327153&lang=2&reg=48$$,
$$National Statistical Office, Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-10-23$$,
$$["PLFS has been conducted by NSO since 2017.","NSO proposes changes from January 2027 with a new Panel 6 sampling frame.","A separate Second Stage Stratum is proposed for digital-platform workers.","New questions would cover unpaid household and caregiving activities, volunteer work and unpaid trainee work."]$$::jsonb,
$$[{"question":"Why would NSO introduce a separate stratum for digital-platform workers?","answer":"The release says the earlier arrangement did not capture an adequate number of such workers; the new stratum is intended to improve coverage."}]$$::jsonb,
$${"title":"How a labour survey evolves","steps":["A sampling frame determines who can be selected.","Strata improve representation of important groups.","Question schedules determine the information collected.","Estimation procedures turn sample responses into published indicators."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-exercise-simbex-2026$$, $$2026-10-27$$,
$$SIMBEX-2026 brings India and Singapore together for its 33rd maritime exercise$$,
$$The 33rd Singapore-India Maritime Bilateral Exercise, SIMBEX-2026, was held at Visakhapatnam from 21 to 26 October. The harbour and sea phases included professional exchanges and drills in anti-submarine, anti-surface and anti-air warfare.$$,
$$Bilateral exercises are frequent prelims material. This brief supports questions on India-Singapore defence cooperation, maritime security and the Bay of Bengal without confusing a training activity with a treaty alliance.$$,
$$SIMBEX began in 1994 as Exercise Lion King. The 2026 edition involved the Republic of Singapore Navy ship RSS Supreme. The harbour phase preceded the sea phase, where the two navies undertook tactical and maritime operations. Such exercises build interoperability—the ability of forces to communicate and work together—rather than creating a mutual-defence treaty.$$,
$$33rd edition of Singapore-India Maritime Bilateral Exercise (SIMBEX-2026) commences at Visakhapatnam$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2326348&lang=1&reg=48$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-10-21$$,
$$["SIMBEX is the Singapore-India Maritime Bilateral Exercise.","The 2026 edition is the 33rd and was held at Visakhapatnam from 21 to 26 October.","SIMBEX began in 1994 as Exercise Lion King.","The sea phase included anti-submarine, anti-surface and anti-air warfare drills."]$$::jsonb,
$$[{"question":"What did SIMBEX originally begin as?","answer":"It began in 1994 as Exercise Lion King."}]$$::jsonb,
$${"title":"A bilateral naval exercise","steps":["Partner navies bring ships and personnel together.","The harbour phase supports planning and professional exchanges.","The sea phase tests coordinated maritime drills.","Repeated exercises improve interoperability and maritime cooperation."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-aatal-delhi-ncr-air-pollution-facility$$, $$2026-10-27$$,
$$AATAL facility opens to analyse Delhi-NCR air pollution beyond AQI readings$$,
$$The Ministry of Earth Sciences inaugurated the Integrated Atmospheric Chemistry and Aerosol Toxicity Analysis Laboratory (AATAL) at IITM’s Delhi Branch. It is intended to identify pollutant composition, sources, relative contributions and potential health implications in real time.$$,
$$This has direct environment and science value: it separates an AQI reading from source apportionment, which identifies where pollutants come from and can guide targeted controls.$$,
$$AATAL is established under Mission Mausam, according to the official release, and is integrated with AIRWISE. AQI communicates an air-quality condition through an index; it does not by itself identify the pollutant source. Source apportionment uses chemical and atmospheric analysis to estimate contributions from different sources, helping bodies such as CAQM and pollution-control agencies assess interventions.$$,
$$World’s first-of-its-kind Air Pollution Analysis facility for Delhi NCR inaugurated$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2327957&lang=1&reg=3$$,
$$Ministry of Earth Sciences / Press Information Bureau$$, $$2026-10-24$$,
$$["AATAL stands for Integrated Atmospheric Chemistry and Aerosol Toxicity Analysis Laboratory.","It was inaugurated at IITM’s Delhi Branch for Delhi-NCR air-pollution analysis.","The release links the facility to Mission Mausam and AIRWISE.","It aims to support real-time source apportionment, forecasting and intervention assessment."]$$::jsonb,
$$[{"question":"What does source apportionment add beyond an AQI value?","answer":"It estimates the pollutant sources and their relative contributions, which can guide more targeted action."}]$$::jsonb,
$${"title":"From air measurement to action","steps":["Sensors and instruments identify pollutants.","Chemical analysis examines composition and toxicity.","Source apportionment estimates contributing sources.","Forecasts and evidence help authorities target interventions."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-drdo-aip-energy-module-stw-2$$, $$2026-10-27$$,
$$DRDO’s indigenous AIP energy module reaches Setting-to-Work Phase 2$$,
$$DRDO’s Naval Materials Research Laboratory completed the Setting-to-Work Phase 2 milestone for an indigenous Air Independent Propulsion energy module for diesel-electric submarines. The next phase is power-production testing before planned integration with a Kalvari-class submarine.$$,
$$This is a defence-technology concept brief. It tests why an air-independent propulsion system matters for conventional submarines and distinguishes a technical milestone from operational induction.$$,
$$A diesel-electric submarine normally needs access to atmospheric oxygen for battery charging through its diesel engines. An AIP system can increase underwater endurance by reducing that dependence. The official release says the energy module will next be energised and tested under Indian Navy protocols before handover to Mazagon Dock Shipbuilders Limited for planned early-2027 integration. Therefore it should not be described as already deployed on a submarine.$$,
$$Indigenous AIP system for Indian Navy diesel-electric submarines achieves Setting-to-Work Phase 2 milestone$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2328040&lang=1&reg=3$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-10-24$$,
$$["The AIP Energy Module was developed by DRDO’s Naval Materials Research Laboratory.","AIP boosts the underwater endurance of diesel-electric submarines.","The reported milestone is Setting-to-Work Phase 2.","The release places power-production testing before planned integration with a Kalvari-class submarine."]$$::jsonb,
$$[{"question":"Why can an AIP system improve a diesel-electric submarine’s underwater endurance?","answer":"It reduces dependence on atmospheric oxygen, allowing the submarine to remain submerged longer before needing to surface or snorkel."}]$$::jsonb,
$${"title":"AIP development path","steps":["DRDO develops an energy module.","STW-2 marks a technical preparation milestone.","The module is energised and tested for power production.","After Navy testing, it can move toward submarine integration."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-bihar-integrated-manufacturing-city-gaya$$, $$2026-10-27$$,
$$NICDC launches Bihar Integrated Manufacturing City Gaya Limited$$,
$$The National Industrial Corridor Development Corporation formally launched Bihar Integrated Manufacturing City Gaya Limited at Bodh Gaya. The release reports 12 MoUs for about 300 acres at the IMC Gaya, with proposed investments of Rs 4,200 crore.$$,
$$The development links industrial corridors, State-level manufacturing infrastructure and investment facilitation—useful for economy and cooperative-federalism questions.$$,
$$NICDC is the National Industrial Corridor Development Corporation. The new entity is linked to the Integrated Manufacturing City at Gaya; the cited MoUs represent proposed investment and land commitments, not proof that the projects have already been completed or that the entire proposed value has been invested. Industrial corridors seek to combine logistics, infrastructure and planned industrial development.$$,
$$NICDC advances industrial development in Bihar with launch of Bihar Integrated Manufacturing City Gaya Limited$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2328067&lang=1&reg=3$$,
$$Ministry of Commerce and Industry / Press Information Bureau$$, $$2026-10-24$$,
$$["NICDC stands for National Industrial Corridor Development Corporation.","Bihar Integrated Manufacturing City Gaya Limited was formally launched at Bodh Gaya.","The release cites 12 MoUs for approximately 300 acres at IMC Gaya.","The associated proposed investment figure is Rs 4,200 crore."]$$::jsonb,
$$[{"question":"Do the 12 MoUs prove that all Rs 4,200 crore has already been invested?","answer":"No. The release describes them as proposed investments associated with MoUs."}]$$::jsonb,
$${"title":"Industrial-corridor development","steps":["Public agencies plan industrial infrastructure.","A city-level development vehicle is launched.","Investors express interest through MoUs and land commitments.","Projects move through approvals, construction and operations."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-27-rbi-bhubaneswar-data-centre-cybersecurity-institute$$, $$2026-10-27$$,
$$RBI opens a Tier IV data-centre facility and cybersecurity training institute in Bhubaneswar$$,
$$The Prime Minister inaugurated the Reserve Bank of India’s new Data Centre and Cybersecurity Training Institute in Bhubaneswar. The facility is intended to support payment and settlement systems and capacity building for the banking, financial services and insurance sector.$$,
$$This finance-and-digital-governance brief helps students connect central-bank infrastructure, payment-system resilience and cyber-capability building rather than treating the facility as a consumer bank or a new digital-currency scheme.$$,
$$The official release says four data centres will host mission-critical payment and settlement systems and that the facility is certified to Uptime Institute Tier IV standard. Tier IV is a data-centre resilience classification, not an RBI regulatory grade for commercial banks. The institute’s stated focus includes cybersecurity, enterprise technology, quantum computing and AI relevant to the BFSI sector.$$,
$$Prime Minister inaugurates RBI’s Data Centre and Cybersecurity Training Institute in Bhubaneswar$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2328250&lang=1&reg=3$$,
$$Prime Minister’s Office / Press Information Bureau$$, $$2026-10-25$$,
$$["The new facilities are in Bhubaneswar, Odisha.","The data-centre facility supports RBI computing needs and mission-critical payment and settlement systems.","The release says it has Uptime Institute Tier IV certification.","The Cybersecurity Training Institute is intended for training, research and capability development in the BFSI sector."]$$::jsonb,
$$[{"question":"What does Tier IV refer to in this release?","answer":"It refers to the Uptime Institute’s data-centre infrastructure resilience classification, not an RBI rating for banks."}]$$::jsonb,
$${"title":"Resilient financial digital infrastructure","steps":["Critical payment systems need secure computing capacity.","Tier IV infrastructure strengthens resilience and continuity.","Cybersecurity training builds sector capability.","Reliable systems support digital financial services and settlement."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
