where briefs.slug in (
$$2026-10-27-pm-samajik-sahayata-yojana$$,
$$2026-10-27-flex-fuel-e85-e100-cmvr-amendment$$,
$$2026-10-27-nsdc-social-stock-exchange-debut$$,
$$2026-10-27-enhanced-nmms-vb-g-ram-g$$,
$$2026-10-27-plfs-2027-sampling-consultation$$,
$$2026-10-27-exercise-simbex-2026$$,
$$2026-10-27-aatal-delhi-ncr-air-pollution-facility$$,
$$2026-10-27-drdo-aip-energy-module-stw-2$$,
$$2026-10-27-bihar-integrated-manufacturing-city-gaya$$,
$$2026-10-27-rbi-bhubaneswar-data-centre-cybersecurity-institute$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
